// spec: .qa/e2e/specs/guided-prayer.md
// seed: tests/seed.user1.spec.ts
// NOTE: меню нусаха (aria-disabled у «עדות המזרח») проверено в живом браузере на 1440; полный цикл «החלף» не прогонялся вживую (не менять нусах), написан по плану и по существующему ns-02.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

async function counterText(page: Page) {
  const body = await page.locator('body').innerText();
  return (body.match(/\d+ מתוך \d+/) ?? [''])[0];
}

test.describe('Молитва по шагам', () => {
  test('GP-03 Нусах: עדות המזרח «בקרוב», смена на уровне всей молитвы с подтверждением и возвратом #ecda5d38 @prod-safe @mobile', async ({ page }) => {
    // 1. Сохранить `localStorage['prayer-progress']`.
    await page.goto('/home');
    await expect(page.getByRole('button', { name: 'התחל תפילה' })).toBeVisible({ timeout: 20_000 });
    const saved = await page.evaluate(() => localStorage.getItem('prayer-progress'));
    try {
      // 2. Открыть `/prayer/mincha_ashkenaz`; «קודם» до «1 מתוך 8»; «המשך» 3 раза → «4 מתוך 8», «נפילת אפים».
      await page.goto('/prayer/mincha_ashkenaz');
      await expect(page.getByText(/\d+ מתוך \d+/).first()).toBeVisible();
      const prev = page.getByText('קודם', { exact: true });
      for (let i = 0; i < 15; i++) {
        if ((await counterText(page)) === '1 מתוך 8') break;
        await prev.click();
      }
      await expect(page.getByText('1 מתוך 8')).toBeVisible();
      const next = page.getByText('המשך', { exact: true });
      for (let i = 2; i <= 4; i++) {
        await next.click();
        await expect(page.getByText(`${i} מתוך 8`)).toBeVisible();
      }
      await expect(page.getByText('נפילת אפים', { exact: true })).toBeVisible();

      // 3. Нажать «בחירת נוסח» → список.
      await page.getByLabel(/^בחירת נוסח/).click();
      await expect(page.getByRole('radio', { name: /אשכנזי/ })).toHaveAttribute('aria-checked', 'true');
      await expect(page.getByRole('radio', { name: 'ספרדי' })).toBeVisible();
      const edot = page.getByRole('radio', { name: /עדות המזרח/ });
      await expect(edot).toContainText('בקרוב');
      await expect(edot).toHaveAttribute('aria-disabled', 'true');

      // 4. «ספרדי» → диалог → «ביטול».
      await page.getByRole('radio', { name: 'ספרדי' }).click();
      const confirm = page.getByRole('alert');
      await expect(confirm.getByText('להחליף את התפילה לנוסח ספרד?')).toBeVisible();
      await expect(confirm.getByText('תועבר לקטע המקביל ״נפילת אפיים״.')).toBeVisible();
      await confirm.getByRole('button', { name: 'ביטול' }).click();
      await expect(page.getByRole('alert')).toHaveCount(0);
      await expect(page.getByRole('heading', { level: 1, name: 'מנחה (אשכנזי)' })).toBeVisible();
      await expect(page.getByText('4 מתוך 8')).toBeVisible();

      // 5. Снова «בחירת נוסח» → «ספרדי» → «החלף».
      await page.getByLabel(/^בחירת נוסח/).click();
      await page.getByRole('radio', { name: 'ספרדי' }).click();
      await page.getByRole('alert').getByRole('button', { name: 'החלף' }).click();
      await expect(page).toHaveURL(/\/prayer\/mincha_sfarad/);
      await expect(page.getByRole('heading', { level: 1, name: 'מנחה (ספרדי)' })).toBeVisible();
      await expect(page.getByText('6 מתוך 11')).toBeVisible();
      await expect(page.getByText('נפילת אפיים', { exact: true })).toBeVisible();

      // 6. Вернуть: «בחירת נוסח» → «אשכנזי» → «החלף».
      await page.getByLabel(/^בחירת נוסח/).click();
      await page.getByRole('radio', { name: 'אשכנזי' }).click();
      await page.getByRole('alert').getByRole('button', { name: 'החלף' }).click();
      await expect(page).toHaveURL(/\/prayer\/mincha_ashkenaz/);
      await expect(page.getByRole('heading', { level: 1, name: 'מנחה (אשכנזי)' })).toBeVisible();
      await expect(page.getByText('4 מתוך 8')).toBeVisible();

      // 7. Перейти в `/profile`, прочитать «נוסח תפילה» — профильный нусах не изменился.
      await page.goto('/profile');
      await expect(page.getByText('נוסח תפילה', { exact: true }).first()).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText('אשכנז', { exact: true }).first()).toBeVisible();
    } finally {
      // 8. Уборка: вернуть сохранённое значение `prayer-progress`.
      await page.goto('/home');
      await page.evaluate((v) => {
        if (v === null) localStorage.removeItem('prayer-progress');
        else localStorage.setItem('prayer-progress', v);
      }, saved);
    }
  });
});
